-- Immutable migration snapshot, derived from physical design v0.1. No seed.
CREATE SCHEMA layer1;
CREATE TABLE layer1.institution_register_version (id uuid NOT NULL DEFAULT gen_random_uuid(), source_reference text NOT NULL, source_sha256 text NOT NULL, received_at timestamptz NOT NULL, imported_at timestamptz, row_count integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'staged', created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT pk_institution_register_version PRIMARY KEY (id), CONSTRAINT ck_institution_register_version_1 CHECK (source_sha256 ~ '^[0-9a-f]{64}$'), CONSTRAINT ck_institution_register_version_2 CHECK (row_count >= 0), CONSTRAINT ck_institution_register_version_3 CHECK (status IN ('staged', 'applied', 'failed')), CONSTRAINT ck_institution_register_version_4 CHECK ((status = 'applied') = (imported_at IS NOT NULL)), CONSTRAINT ck_institution_register_version_5 CHECK (length(btrim(source_reference)) > 0));
COMMENT ON TABLE layer1.institution_register_version IS 'Provenance and immutable version of an institution register import';
COMMENT ON COLUMN layer1.institution_register_version.id IS 'Stable import version identifier [internal]';
COMMENT ON COLUMN layer1.institution_register_version.source_reference IS 'Document reference or approved source URL; no uploaded document content [internal]';
COMMENT ON COLUMN layer1.institution_register_version.source_sha256 IS 'Lowercase SHA-256 of source bytes [internal]';
COMMENT ON COLUMN layer1.institution_register_version.received_at IS 'Source receipt instant [internal]';
COMMENT ON COLUMN layer1.institution_register_version.imported_at IS 'Successful import completion instant [internal]';
COMMENT ON COLUMN layer1.institution_register_version.row_count IS 'Validated accepted source rows; importer reconciles actual rows [internal]';
COMMENT ON COLUMN layer1.institution_register_version.status IS 'staged, applied or failed; applied versions immutable [internal]';
COMMENT ON COLUMN layer1.institution_register_version.created_at IS 'Creation instant [internal]';
CREATE TABLE layer1.institution (id uuid NOT NULL DEFAULT gen_random_uuid(), register_version_id uuid NOT NULL, source_key text, name text NOT NULL, institution_type text, institution_level text, institution_region text, active boolean NOT NULL DEFAULT TRUE, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT pk_institution PRIMARY KEY (id), CONSTRAINT uq_institution_1 UNIQUE (source_key), CONSTRAINT ck_institution_1 CHECK (length(btrim(name)) > 0), CONSTRAINT ck_institution_2 CHECK (source_key IS NULL OR length(btrim(source_key)) > 0));
COMMENT ON TABLE layer1.institution IS 'Stable institution identity and latest register attributes';
COMMENT ON COLUMN layer1.institution.id IS 'Stable identity independent of name or user replacement [public_id]';
COMMENT ON COLUMN layer1.institution.register_version_id IS 'Source version for latest attributes [internal]';
COMMENT ON COLUMN layer1.institution.source_key IS 'Canonical cross-version source identity; importer must adjudicate missing keys [internal]';
COMMENT ON COLUMN layer1.institution.name IS 'Latest official name; exports use cycle snapshot name [internal]';
COMMENT ON COLUMN layer1.institution.institution_type IS 'Latest source type code [internal]';
COMMENT ON COLUMN layer1.institution.institution_level IS 'Latest source level code [internal]';
COMMENT ON COLUMN layer1.institution.institution_region IS 'Latest source region code [internal]';
COMMENT ON COLUMN layer1.institution.active IS 'Available for future cycle configuration, not historical denominator [internal]';
COMMENT ON COLUMN layer1.institution.created_at IS 'Creation instant [internal]';
COMMENT ON COLUMN layer1.institution.updated_at IS 'Last service mutation instant [internal]';
CREATE TABLE layer1.cycle (id uuid NOT NULL DEFAULT gen_random_uuid(), year integer NOT NULL, opens_at timestamptz NOT NULL, closes_at timestamptz NOT NULL, timezone text NOT NULL, licence_text text NOT NULL, licence_url text NOT NULL, revision bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT pk_cycle PRIMARY KEY (id), CONSTRAINT uq_cycle_1 UNIQUE (year), CONSTRAINT ck_cycle_1 CHECK (year BETWEEN 2000 AND 9999), CONSTRAINT ck_cycle_2 CHECK (opens_at < closes_at), CONSTRAINT ck_cycle_3 CHECK (revision >= 1), CONSTRAINT ck_cycle_4 CHECK (length(btrim(timezone)) > 0), CONSTRAINT ck_cycle_5 CHECK (length(btrim(licence_text)) > 0), CONSTRAINT ck_cycle_6 CHECK (licence_url ~ '^https?://'));
COMMENT ON TABLE layer1.cycle IS 'Annual collection window and public export licence';
COMMENT ON COLUMN layer1.cycle.id IS 'Stable annual cycle identifier [internal]';
COMMENT ON COLUMN layer1.cycle.year IS 'Feed year; one cycle per year [public]';
COMMENT ON COLUMN layer1.cycle.opens_at IS 'Inclusive opening instant [internal]';
COMMENT ON COLUMN layer1.cycle.closes_at IS 'Exclusive closing instant; extensions audited [internal]';
COMMENT ON COLUMN layer1.cycle.timezone IS 'IANA display zone validated by service; timestamps stored as instants [internal]';
COMMENT ON COLUMN layer1.cycle.licence_text IS 'Export licence text; external confirmation required for production [public]';
COMMENT ON COLUMN layer1.cycle.licence_url IS 'Absolute HTTP(S) licence URI; service performs URI validation [public]';
COMMENT ON COLUMN layer1.cycle.revision IS 'Optimistic version for settings and denominator mutations [internal]';
COMMENT ON COLUMN layer1.cycle.created_at IS 'Creation instant [internal]';
COMMENT ON COLUMN layer1.cycle.updated_at IS 'Last settings mutation instant [internal]';
CREATE TABLE layer1.cycle_institution (cycle_id uuid NOT NULL, institution_id uuid NOT NULL, register_version_id uuid NOT NULL, name text NOT NULL, institution_type text, institution_level text, institution_region text, snapshotted_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT pk_cycle_institution PRIMARY KEY (cycle_id, institution_id), CONSTRAINT ck_cycle_institution_1 CHECK (length(btrim(name)) > 0));
COMMENT ON TABLE layer1.cycle_institution IS 'Explicit annual denominator and institution attribute snapshot';
COMMENT ON COLUMN layer1.cycle_institution.cycle_id IS 'Cycle membership key [internal]';
COMMENT ON COLUMN layer1.cycle_institution.institution_id IS 'Stable institution identifier [public]';
COMMENT ON COLUMN layer1.cycle_institution.register_version_id IS 'Source version of this annual snapshot [internal]';
COMMENT ON COLUMN layer1.cycle_institution.name IS 'Annual official name used by public/internal feeds [public]';
COMMENT ON COLUMN layer1.cycle_institution.institution_type IS 'Annual institution type code [public]';
COMMENT ON COLUMN layer1.cycle_institution.institution_level IS 'Annual institution level code [public]';
COMMENT ON COLUMN layer1.cycle_institution.institution_region IS 'Annual institution region code [public]';
COMMENT ON COLUMN layer1.cycle_institution.snapshotted_at IS 'Snapshot capture instant [internal]';
CREATE TABLE layer1.account (id uuid NOT NULL DEFAULT gen_random_uuid(), institution_id uuid, role text NOT NULL, name text NOT NULL, email text NOT NULL, normalized_email text NOT NULL, password_hash text NOT NULL, status text NOT NULL DEFAULT 'pending', requested_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_by uuid, reviewed_at timestamptz, approved_at timestamptz, inactive_at timestamptz, decision_reason text, approval_reference text, domain_policy_id uuid, must_change_password boolean NOT NULL DEFAULT FALSE, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT pk_account PRIMARY KEY (id), CONSTRAINT uq_account_1 UNIQUE (normalized_email), CONSTRAINT ck_account_1 CHECK (role IN ('institution_user', 'ADMIN_MPALSG', 'ADMIN_ITE')), CONSTRAINT ck_account_2 CHECK ((role = 'institution_user') = (institution_id IS NOT NULL)), CONSTRAINT ck_account_3 CHECK (status IN ('pending', 'approved', 'rejected', 'inactive')), CONSTRAINT ck_account_4 CHECK (normalized_email = lower(btrim(email)) AND length(normalized_email) > 3), CONSTRAINT ck_account_5 CHECK (length(btrim(name)) > 0 AND length(password_hash) > 0), CONSTRAINT ck_account_6 CHECK ((status = 'inactive') = (inactive_at IS NOT NULL)), CONSTRAINT ck_account_7 CHECK (status <> 'approved' OR approved_at IS NOT NULL), CONSTRAINT ck_account_8 CHECK (status NOT IN ('approved', 'rejected') OR role <> 'institution_user' OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL AND reviewed_by <> id)), CONSTRAINT ck_account_9 CHECK (status <> 'approved' OR role <> 'institution_user' OR (domain_policy_id IS NOT NULL AND approval_reference IS NOT NULL AND length(btrim(approval_reference)) > 0)), CONSTRAINT ck_account_10 CHECK (status <> 'rejected' OR (decision_reason IS NOT NULL AND length(btrim(decision_reason)) > 0)));
COMMENT ON TABLE layer1.account IS 'Institution request and administrator account; no mailbox verification';
COMMENT ON COLUMN layer1.account.id IS 'Stable account identifier [internal]';
COMMENT ON COLUMN layer1.account.institution_id IS 'Mandatory only for institution_user; administrative accounts have no owning institution [internal_feed]';
COMMENT ON COLUMN layer1.account.role IS 'institution_user, ADMIN_MPALSG or ADMIN_ITE [internal_feed]';
COMMENT ON COLUMN layer1.account.name IS 'Applicant display name; not public [restricted]';
COMMENT ON COLUMN layer1.account.email IS 'Original institution email; protected optional email profile only [internal_feed]';
COMMENT ON COLUMN layer1.account.normalized_email IS 'trimmed lowercase email for uniqueness; validated email syntax and IDNA domain by service [restricted]';
COMMENT ON COLUMN layer1.account.password_hash IS 'Password hash including algorithm metadata; never exported [secret_hash]';
COMMENT ON COLUMN layer1.account.status IS 'pending, approved, rejected or inactive [internal_feed]';
COMMENT ON COLUMN layer1.account.requested_at IS 'Request receipt for registration indicator, including pending/rejected [internal]';
COMMENT ON COLUMN layer1.account.reviewed_by IS 'Reviewing administrator; approved institution user cannot self-review [restricted]';
COMMENT ON COLUMN layer1.account.reviewed_at IS 'Most recent approval or rejection review instant [restricted]';
COMMENT ON COLUMN layer1.account.approved_at IS 'Approval instant retained after deactivation [restricted]';
COMMENT ON COLUMN layer1.account.inactive_at IS 'Deactivation instant [restricted]';
COMMENT ON COLUMN layer1.account.decision_reason IS 'Review reason; required for rejection [restricted]';
COMMENT ON COLUMN layer1.account.approval_reference IS 'Restricted official correspondence reference; no document upload [restricted]';
COMMENT ON COLUMN layer1.account.domain_policy_id IS 'Exact institutional domain policy used at approval [restricted]';
COMMENT ON COLUMN layer1.account.must_change_password IS 'Force password change after manual recovery [internal]';
COMMENT ON COLUMN layer1.account.created_at IS 'Creation instant [internal]';
COMMENT ON COLUMN layer1.account.updated_at IS 'Last account mutation instant [internal]';
CREATE TABLE layer1.institution_email_domain (id uuid NOT NULL DEFAULT gen_random_uuid(), institution_id uuid NOT NULL, normalized_domain text NOT NULL, active boolean NOT NULL DEFAULT TRUE, verified_by uuid NOT NULL, verified_at timestamptz NOT NULL, evidence_reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT pk_institution_email_domain PRIMARY KEY (id), CONSTRAINT uq_institution_email_domain_1 UNIQUE (institution_id, id), CONSTRAINT ck_institution_email_domain_1 CHECK (normalized_domain = lower(btrim(normalized_domain))), CONSTRAINT ck_institution_email_domain_2 CHECK (normalized_domain ~ '^[a-z0-9]([a-z0-9.-]*[a-z0-9])?$' AND position('.' IN normalized_domain) > 0), CONSTRAINT ck_institution_email_domain_3 CHECK (length(btrim(evidence_reference)) > 0));
COMMENT ON TABLE layer1.institution_email_domain IS 'Versioned exact-domain policy with official evidence and reviewer';
COMMENT ON COLUMN layer1.institution_email_domain.id IS 'Stable policy version id; approved account retains reference [internal]';
COMMENT ON COLUMN layer1.institution_email_domain.institution_id IS 'Institution allowed to use exactly this domain [internal]';
COMMENT ON COLUMN layer1.institution_email_domain.normalized_domain IS 'Lowercase IDNA ASCII domain, no wildcard, suffix matching or @ [restricted]';
COMMENT ON COLUMN layer1.institution_email_domain.active IS 'Policy currently eligible for approval [internal]';
COMMENT ON COLUMN layer1.institution_email_domain.verified_by IS 'Administrator who checked the official domain list [restricted]';
COMMENT ON COLUMN layer1.institution_email_domain.verified_at IS 'Manual policy validation instant; not mailbox verification [restricted]';
COMMENT ON COLUMN layer1.institution_email_domain.evidence_reference IS 'Restricted official source/correspondence reference [restricted]';
COMMENT ON COLUMN layer1.institution_email_domain.created_at IS 'Creation instant [internal]';
CREATE TABLE layer1.session (id uuid NOT NULL DEFAULT gen_random_uuid(), account_id uuid NOT NULL, token_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, last_seen_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, idle_expires_at timestamptz NOT NULL, absolute_expires_at timestamptz NOT NULL, revoked_at timestamptz, CONSTRAINT pk_session PRIMARY KEY (id), CONSTRAINT uq_session_1 UNIQUE (token_hash), CONSTRAINT ck_session_1 CHECK (token_hash ~ '^[0-9a-f]{64}$'), CONSTRAINT ck_session_2 CHECK (created_at <= last_seen_at AND last_seen_at < idle_expires_at AND idle_expires_at <= absolute_expires_at), CONSTRAINT ck_session_3 CHECK (revoked_at IS NULL OR revoked_at >= created_at));
COMMENT ON TABLE layer1.session IS 'Shared server sessions; token stored as digest only';
COMMENT ON COLUMN layer1.session.id IS 'Session identity [internal]';
COMMENT ON COLUMN layer1.session.account_id IS 'Owning account checked on every authenticated request [restricted]';
COMMENT ON COLUMN layer1.session.token_hash IS 'SHA-256 digest of high entropy random session token [secret_hash]';
COMMENT ON COLUMN layer1.session.created_at IS 'Session creation instant [internal]';
COMMENT ON COLUMN layer1.session.last_seen_at IS 'Last accepted activity [internal]';
COMMENT ON COLUMN layer1.session.idle_expires_at IS 'Sliding expiry never beyond absolute expiry [internal]';
COMMENT ON COLUMN layer1.session.absolute_expires_at IS 'Non-sliding hard expiry [internal]';
COMMENT ON COLUMN layer1.session.revoked_at IS 'Explicit invalidation instant [internal]';
CREATE TABLE layer1.account_recovery_grant (id uuid NOT NULL DEFAULT gen_random_uuid(), account_id uuid NOT NULL, issued_by uuid NOT NULL, token_hash text NOT NULL, issued_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at timestamptz NOT NULL, used_at timestamptz, revoked_at timestamptz, identity_check_reference text NOT NULL, CONSTRAINT pk_account_recovery_grant PRIMARY KEY (id), CONSTRAINT uq_account_recovery_grant_1 UNIQUE (token_hash), CONSTRAINT ck_account_recovery_grant_1 CHECK (token_hash ~ '^[0-9a-f]{64}$'), CONSTRAINT ck_account_recovery_grant_2 CHECK (issued_at < expires_at), CONSTRAINT ck_account_recovery_grant_3 CHECK (used_at IS NULL OR (used_at >= issued_at AND used_at < expires_at)), CONSTRAINT ck_account_recovery_grant_4 CHECK (revoked_at IS NULL OR revoked_at >= issued_at), CONSTRAINT ck_account_recovery_grant_5 CHECK (length(btrim(identity_check_reference)) > 0));
COMMENT ON TABLE layer1.account_recovery_grant IS 'Manual one-use recovery; delivery channel remains externally agreed';
COMMENT ON COLUMN layer1.account_recovery_grant.id IS 'Recovery grant identifier [internal]';
COMMENT ON COLUMN layer1.account_recovery_grant.account_id IS 'Target account [restricted]';
COMMENT ON COLUMN layer1.account_recovery_grant.issued_by IS 'Authorised issuing administrator [restricted]';
COMMENT ON COLUMN layer1.account_recovery_grant.token_hash IS 'SHA-256 of high entropy recovery token; never logged [secret_hash]';
COMMENT ON COLUMN layer1.account_recovery_grant.issued_at IS 'Grant creation instant [internal]';
COMMENT ON COLUMN layer1.account_recovery_grant.expires_at IS 'Finite expiration, duration configured by approved policy [internal]';
COMMENT ON COLUMN layer1.account_recovery_grant.used_at IS 'Atomic one-use redemption instant [internal]';
COMMENT ON COLUMN layer1.account_recovery_grant.revoked_at IS 'Explicit revocation instant [internal]';
COMMENT ON COLUMN layer1.account_recovery_grant.identity_check_reference IS 'Evidence reference for manual identity check, no identity document body [restricted]';
CREATE TABLE layer1.theme (id uuid NOT NULL DEFAULT gen_random_uuid(), code text NOT NULL, uri text NOT NULL, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT pk_theme PRIMARY KEY (id), CONSTRAINT uq_theme_1 UNIQUE (code), CONSTRAINT uq_theme_2 UNIQUE (uri), CONSTRAINT ck_theme_1 CHECK (length(btrim(code)) > 0), CONSTRAINT ck_theme_2 CHECK (uri ~ '^https?://'));
COMMENT ON TABLE layer1.theme IS 'Stable EU/custom theme identity';
COMMENT ON COLUMN layer1.theme.id IS 'Theme identity [internal]';
COMMENT ON COLUMN layer1.theme.code IS 'Stable export code [public]';
COMMENT ON COLUMN layer1.theme.uri IS 'Stable absolute HTTP(S) URI; custom theme URI needs approved source [public]';
COMMENT ON COLUMN layer1.theme.created_at IS 'Creation instant [internal]';
CREATE TABLE layer1.theme_translation (theme_id uuid NOT NULL, locale text NOT NULL, label text NOT NULL, CONSTRAINT pk_theme_translation PRIMARY KEY (theme_id, locale), CONSTRAINT ck_theme_translation_1 CHECK (locale IN ('en', 'sr-Latn', 'sr-Cyrl')), CONSTRAINT ck_theme_translation_2 CHECK (length(btrim(label)) > 0));
COMMENT ON TABLE layer1.theme_translation IS 'Three product-language labels; institution free text is not translated';
COMMENT ON COLUMN layer1.theme_translation.theme_id IS 'Theme key [internal]';
COMMENT ON COLUMN layer1.theme_translation.locale IS 'en, sr-Latn or sr-Cyrl [public]';
COMMENT ON COLUMN layer1.theme_translation.label IS 'Nonblank theme label for locale [public]';
CREATE TABLE layer1.cycle_theme (cycle_id uuid NOT NULL, theme_id uuid NOT NULL, active boolean NOT NULL DEFAULT TRUE, CONSTRAINT pk_cycle_theme PRIMARY KEY (cycle_id, theme_id));
COMMENT ON TABLE layer1.cycle_theme IS 'Theme eligibility in an annual cycle';
COMMENT ON COLUMN layer1.cycle_theme.cycle_id IS 'Annual cycle key [internal]';
COMMENT ON COLUMN layer1.cycle_theme.theme_id IS 'Theme key [internal]';
COMMENT ON COLUMN layer1.cycle_theme.active IS 'Eligible for new/changed items; existing submitted reference is retained [internal]';
CREATE TABLE layer1.plan (id uuid NOT NULL DEFAULT gen_random_uuid(), institution_id uuid NOT NULL, cycle_id uuid NOT NULL, status text NOT NULL DEFAULT 'draft', revision bigint NOT NULL DEFAULT 1, first_submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT pk_plan PRIMARY KEY (id), CONSTRAINT uq_plan_1 UNIQUE (institution_id, cycle_id), CONSTRAINT ck_plan_1 CHECK (status IN ('draft', 'submitted')), CONSTRAINT ck_plan_2 CHECK (revision >= 1), CONSTRAINT ck_plan_3 CHECK ((status = 'submitted') = (first_submitted_at IS NOT NULL)), CONSTRAINT ck_plan_4 CHECK (updated_at >= created_at), CONSTRAINT ck_plan_5 CHECK (first_submitted_at IS NULL OR (first_submitted_at >= created_at AND updated_at >= first_submitted_at)));
COMMENT ON TABLE layer1.plan IS 'Institution-owned annual plan, independent of account replacement';
COMMENT ON COLUMN layer1.plan.id IS 'Stable plan identifier [public]';
COMMENT ON COLUMN layer1.plan.institution_id IS 'Owning institution; never reassigned to a user [public]';
COMMENT ON COLUMN layer1.plan.cycle_id IS 'Annual cycle; owner pair must be in annual denominator [internal]';
COMMENT ON COLUMN layer1.plan.status IS 'draft or submitted; no mandatory review stage [internal_feed]';
COMMENT ON COLUMN layer1.plan.revision IS 'Monotonic version for optimistic compare-and-swap [internal]';
COMMENT ON COLUMN layer1.plan.first_submitted_at IS 'Immutable first submit instant; no draft exposure [public]';
COMMENT ON COLUMN layer1.plan.created_at IS 'Creation instant [internal]';
COMMENT ON COLUMN layer1.plan.updated_at IS 'Last committed plan mutation instant, never an incomplete intermediate save [public]';
CREATE TABLE layer1.planned_dataset (id uuid NOT NULL DEFAULT gen_random_uuid(), plan_id uuid NOT NULL, position integer NOT NULL, title text, description text, responsible_department text, planned_quarter smallint, theme_id uuid, personal_data_confirmation boolean NOT NULL DEFAULT FALSE, confirmed_at timestamptz, confirmed_by uuid, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT pk_planned_dataset PRIMARY KEY (id), CONSTRAINT uq_planned_dataset_order UNIQUE (plan_id, position) DEFERRABLE INITIALLY DEFERRED, CONSTRAINT ck_planned_dataset_1 CHECK (position > 0), CONSTRAINT ck_planned_dataset_2 CHECK (planned_quarter IS NULL OR planned_quarter BETWEEN 1 AND 4), CONSTRAINT ck_planned_dataset_3 CHECK (title IS NULL OR length(btrim(title)) > 0), CONSTRAINT ck_planned_dataset_4 CHECK ((personal_data_confirmation AND confirmed_at IS NOT NULL AND confirmed_by IS NOT NULL) OR (NOT personal_data_confirmation AND confirmed_at IS NULL AND confirmed_by IS NULL)));
COMMENT ON TABLE layer1.planned_dataset IS 'Ordered proposed dataset item; incomplete draft is allowed';
COMMENT ON COLUMN layer1.planned_dataset.id IS 'Stable item identifier across edits [public]';
COMMENT ON COLUMN layer1.planned_dataset.plan_id IS 'Parent institution-owned plan [internal]';
COMMENT ON COLUMN layer1.planned_dataset.position IS 'Positive item order; deferred uniqueness supports reorder in one transaction [internal]';
COMMENT ON COLUMN layer1.planned_dataset.title IS 'Dataset title; NULL allowed only until submission [public]';
COMMENT ON COLUMN layer1.planned_dataset.description IS 'Optional original free-text description [public]';
COMMENT ON COLUMN layer1.planned_dataset.responsible_department IS 'Optional department; no personal contact fields [public]';
COMMENT ON COLUMN layer1.planned_dataset.planned_quarter IS 'Optional quarter 1 to 4 [public]';
COMMENT ON COLUMN layer1.planned_dataset.theme_id IS 'NULL permitted in draft; eligibility checked against parent cycle [internal]';
COMMENT ON COLUMN layer1.planned_dataset.personal_data_confirmation IS 'True only after confirmation of current item content [public]';
COMMENT ON COLUMN layer1.planned_dataset.confirmed_at IS 'Confirmation instant for current content; cleared by content mutation [internal]';
COMMENT ON COLUMN layer1.planned_dataset.confirmed_by IS 'Account confirming content; institution checked by service [restricted]';
COMMENT ON COLUMN layer1.planned_dataset.created_at IS 'Creation instant [internal]';
COMMENT ON COLUMN layer1.planned_dataset.updated_at IS 'Last item mutation instant [internal]';
CREATE TABLE layer1.plan_revision (plan_id uuid NOT NULL, revision bigint NOT NULL, saved_by uuid NOT NULL, saved_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, snapshot jsonb NOT NULL, CONSTRAINT pk_plan_revision PRIMARY KEY (plan_id, revision), CONSTRAINT ck_plan_revision_1 CHECK (revision >= 1), CONSTRAINT ck_plan_revision_2 CHECK (jsonb_typeof(snapshot) = 'object'));
COMMENT ON TABLE layer1.plan_revision IS 'Immutable committed business snapshot; restricted and not an export';
COMMENT ON COLUMN layer1.plan_revision.plan_id IS 'Plan identity [internal]';
COMMENT ON COLUMN layer1.plan_revision.revision IS 'Exact committed plan revision [internal]';
COMMENT ON COLUMN layer1.plan_revision.saved_by IS 'Authenticated institution actor [restricted]';
COMMENT ON COLUMN layer1.plan_revision.saved_at IS 'Committed revision creation instant [internal]';
COMMENT ON COLUMN layer1.plan_revision.snapshot IS 'Versioned plan/item snapshot; no account/email/hash/token fields [restricted]';
CREATE TABLE layer1.audit_event (id uuid NOT NULL DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, occurred_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, request_id uuid NOT NULL, changes jsonb NOT NULL DEFAULT CAST('{"version":1}' AS jsonb), CONSTRAINT pk_audit_event PRIMARY KEY (id), CONSTRAINT ck_audit_event_1 CHECK (length(btrim(action)) > 0 AND length(btrim(entity_type)) > 0), CONSTRAINT ck_audit_event_2 CHECK (jsonb_typeof(changes) = 'object'));
COMMENT ON TABLE layer1.audit_event IS 'Append-only allowlisted administrative and security audit';
COMMENT ON COLUMN layer1.audit_event.id IS 'Audit identity [internal]';
COMMENT ON COLUMN layer1.audit_event.actor_id IS 'Authenticated actor or NULL for explicitly named system operation [restricted]';
COMMENT ON COLUMN layer1.audit_event.action IS 'Allowlisted action code; never raw request path or credentials [restricted]';
COMMENT ON COLUMN layer1.audit_event.entity_type IS 'Allowlisted logical entity type [restricted]';
COMMENT ON COLUMN layer1.audit_event.entity_id IS 'Logical target id; polymorphic target is not a physical FK [restricted]';
COMMENT ON COLUMN layer1.audit_event.occurred_at IS 'Audit creation instant [internal]';
COMMENT ON COLUMN layer1.audit_event.request_id IS 'Server generated correlation id, no client secret [internal]';
COMMENT ON COLUMN layer1.audit_event.changes IS 'Allowlisted change summary with redaction; no passwords, hashes, tokens or raw request bodies [restricted]';
ALTER TABLE layer1.institution ADD CONSTRAINT fk_institution_1 FOREIGN KEY (register_version_id) REFERENCES layer1.institution_register_version (id) ON DELETE RESTRICT;
ALTER TABLE layer1.cycle_institution ADD CONSTRAINT fk_cycle_institution_1 FOREIGN KEY (cycle_id) REFERENCES layer1.cycle (id) ON DELETE RESTRICT;
ALTER TABLE layer1.cycle_institution ADD CONSTRAINT fk_cycle_institution_2 FOREIGN KEY (institution_id) REFERENCES layer1.institution (id) ON DELETE RESTRICT;
ALTER TABLE layer1.cycle_institution ADD CONSTRAINT fk_cycle_institution_3 FOREIGN KEY (register_version_id) REFERENCES layer1.institution_register_version (id) ON DELETE RESTRICT;
ALTER TABLE layer1.account ADD CONSTRAINT fk_account_1 FOREIGN KEY (institution_id) REFERENCES layer1.institution (id) ON DELETE RESTRICT;
ALTER TABLE layer1.account ADD CONSTRAINT fk_account_2 FOREIGN KEY (reviewed_by) REFERENCES layer1.account (id) ON DELETE RESTRICT;
ALTER TABLE layer1.account ADD CONSTRAINT fk_account_3 FOREIGN KEY (institution_id, domain_policy_id) REFERENCES layer1.institution_email_domain (institution_id, id) ON DELETE RESTRICT;
ALTER TABLE layer1.institution_email_domain ADD CONSTRAINT fk_institution_email_domain_1 FOREIGN KEY (institution_id) REFERENCES layer1.institution (id) ON DELETE RESTRICT;
ALTER TABLE layer1.institution_email_domain ADD CONSTRAINT fk_institution_email_domain_2 FOREIGN KEY (verified_by) REFERENCES layer1.account (id) ON DELETE RESTRICT;
